const fs = require('fs');
const path = require('path');
const out = [];
const ALLOWED_PREFIXES = ['ui/', 'n8n/workflows/'];
const ALLOWED_FILES = ['docker-compose.yml'];
const AUDIT_LOG = '/host-repo/deploy/webhook_audit.log';

function audit(entry) {
  try {
    const line = JSON.stringify(Object.assign({ ts: new Date().toISOString() }, entry)) + '\n';
    fs.appendFileSync(AUDIT_LOG, line);
  } catch (e) { /* audit logging must never block the response */ }
}

function isAllowed(relPath) {
  const norm = String(relPath).replace(/\\/g, '/');
  if (ALLOWED_FILES.includes(norm)) return true;
  return ALLOWED_PREFIXES.some(p => norm.startsWith(p));
}

for (const item of items) {
  const j = item.json || {};
  const body = j.body || {};
  const relPath = body.path;
  try {
    const b64 = body.content_b64;
    if (!relPath || typeof b64 !== 'string') {
      audit({ path: relPath || null, ok: false, error: 'missing path or content_b64' });
      out.push({json:{ok:false,error:'missing path or content_b64'}});
      continue;
    }
    if (!isAllowed(relPath)) {
      audit({ path: relPath, ok: false, error: 'path not in allowlist' });
      out.push({json:{ok:false,error:'path not in allowlist'}});
      continue;
    }
    const root = path.resolve('/host-repo');
    const target = path.resolve(root, relPath);
    if (target !== root && !target.startsWith(root + path.sep)) {
      audit({ path: relPath, ok: false, error: 'path escapes repo root' });
      out.push({json:{ok:false,error:'path escapes repo root'}});
      continue;
    }
    let symlinkFound = false;
    let cursor = target;
    while (cursor !== root && cursor.length >= root.length) {
      try {
        const st = fs.lstatSync(cursor);
        if (st.isSymbolicLink()) { symlinkFound = true; break; }
      } catch (e) { /* does not exist yet, fine */ }
      const parent = path.dirname(cursor);
      if (parent === cursor) break;
      cursor = parent;
    }
    if (symlinkFound) {
      audit({ path: relPath, ok: false, error: 'symlink in target path, refused' });
      out.push({json:{ok:false,error:'symlink in target path, refused'}});
      continue;
    }
    fs.mkdirSync(path.dirname(target), {recursive:true});
    const buf = Buffer.from(b64, 'base64');
    fs.writeFileSync(target, buf);
    audit({ path: relPath, ok: true, bytes: buf.length });
    out.push({json:{ok:true,path:relPath,bytes:buf.length}});
  } catch (e) {
    audit({ path: relPath || null, ok: false, error: String(e && e.message || e) });
    out.push({json:{ok:false,error:String(e && e.message || e)}});
  }
}
return out;
